                                "name": "Untitled Tab",
                                "overrides": {
                                    "composition": [
                                        {
                                            "definition": {
                                                "id": "2d56f06d55f46bbd4e79b5e624beb940",
                                                "type": "MACROPONENT"
                                            },
                                            "elementId": "rich_text_7",
                                            "elementLabel": "Rich text 7",
                                            "eventMappings": [],
                                            "isHidden": {
                                                "type": "JSON_LITERAL",
                                                "value": null
                                            },
                                            "preset": null,
                                            "propertyValues": {
                                                "html": {
                                                    "script": {
                                                        "apiVersion": "2.0.0",
                                                        "controllerElementId": null,
                                                        "inlineScript": "function evaluateProperty({ api, helpers }) {\n    const kpi = api.data.sam_kpi_foundation_1.output.users_kpi;\n    const totalCount = kpi.reduce((sum, kpis) => sum + (kpis.field ? kpis.field_value : 0), 0);\n\n    // ServiceNow-inspired Table Design\n    let tableHtml = `\n        <table id=\"kpi-table\" style=\"width: 100%; border-collapse: collapse; font-family: 'Arial', sans-serif; margin-top: 20px; background-color: #ffffff; border: 1px solid #dcdcdc; border-radius: 4px;\">\n            <thead>\n                <tr style=\"background-color: #f3f4f6; color: #333333; font-size: 14px; text-align: left; border-bottom: 2px solid #dcdcdc;\">\n                    <th style=\"padding: 12px; border-right: 1px solid #e0e0e0;\">KPI</th>\n                    <th style=\"padding: 12px; border-right: 1px solid #e0e0e0;\">Description</th>\n                    <th style=\"padding: 12px; text-align: center; border-right: 1px solid #e0e0e0;\">Count</th>\n                    <th style=\"padding: 12px; text-align: center; border-right: 1px solid #e0e0e0;\">Impact</th>\n                    <th style=\"padding: 12px;\">Recommendation</th>\n                </tr>\n            </thead>\n            <tbody>\n    `;\n\n    // Loop through KPI data to populate rows\n    kpi.forEach((kpis, index) => {\n        let kpiName = kpis.kpi || \"Unknown KPI\";\n        let description = kpis.description || \"No Description\";\n        let count = kpis.field ? kpis.field_value : 0;\n        let recommendation = kpis.recommendation || \"No Action Needed\";\n\n        // Determine Impact Level\n        let impact = \"Low\";\n        let dotColor = \"#28a745\"; // Green for Low Impact\n        \n        if (count >= totalCount / 2) {\n            impact = \"High\";\n            dotColor = \"#ff4d4f\"; // Red for High Impact\n        } else if (count > 2) {\n            impact = \"Medium\";\n            dotColor = \"#ffc107\"; // Yellow for Medium Impact\n        }\n\n        // Row Color Alternating\n        let rowBackground = index % 2 === 0 ? \"#ffffff\" : \"#f8f9fa\";\n\n        // Generate Row\n        tableHtml += `\n            <tr data-impact=\"${impact}\" style=\"background-color: ${rowBackground}; transition: background-color 0.2s ease;\">\n                <td style=\"padding: 12px; border-bottom: 1px solid #e0e0e0; font-weight: 500; color: #333333;\">${kpiName}</td>\n                <td style=\"padding: 12px; border-bottom: 1px solid #e0e0e0; color: #666666;\">${description}</td>\n                <td style=\"padding: 12px; text-align: center; border-bottom: 1px solid #e0e0e0; font-weight: bold; color: #000000;\">${count}</td>\n                <td style=\"padding: 12px; text-align: center; border-bottom: 1px solid #e0e0e0;\">\n                    <span style=\"display: inline-flex; align-items: center; gap: 6px; font-weight: 600; color: #000000;\">\n                        <span style=\"display: inline-block; width: 10px; height: 10px; background-color: ${dotColor}; border-radius: 50%;\"></span>\n                        ${impact}\n                    </span>\n                </td>\n                <td style=\"padding: 12px; border-bottom: 1px solid #e0e0e0; color: #0072c6; font-weight: 500;\">${recommendation}</td>\n            </tr>\n        `;\n    });\n\n    // Close the Table\n    tableHtml += `\n            </tbody>\n        </table>\n    `;\n\n    // Return the Full HTML (only table content)\n    return tableHtml;\n}\n",
                                                        "scriptSysId": "eb57050ec31e96100ced12f1b40131c3",
                                                        "target": null
                                                    },
                                                    "type": "CLIENT_TRANSFORM_SCRIPT"
                                                }
