                                                        "inlineScript": "function evaluateProperty({ api, helpers }) {\n    const kpi = api.data.sam_kpi_foundation_1.output.company_kpi;\n    const totalCount = kpi.reduce((sum, kpis) => sum + (kpis.field ? kpis.field_value : 0), 0);\n\n    console.log(\"kalai\", JSON.stringify(kpi, null, 4));\n\n    // Initialize the HTML table\n    let tableHtml = `\n       <table id=\"kpi-table\" style=\"width: 100%; border-collapse: collapse; font-family: 'Arial', sans-serif; margin-top: 20px; background-color: #ffffff; border: 1px solid #dcdcdc; border-radius: 4px;\">\n            <thead>\n                <tr style=\"background-color: #f3f4f6; color: #333333; font-size: 14px; text-align: left; border-bottom: 2px solid #dcdcdc;\">\n                    <th style=\"padding: 12px; border-right: 1px solid #e0e0e0;\">KPI</th>\n                    <th style=\"padding: 12px; border-right: 1px solid #e0e0e0;\">Description</th>\n                    <th style=\"padding: 12px; text-align: center; border-right: 1px solid #e0e0e0;\">Count</th>\n                    <th style=\"padding: 12px; text-align: center; border-right: 1px solid #e0e0e0;\">Impact</th>\n                    <th style=\"padding: 12px;\">Recommendation</th>\n                </tr>\n            </thead>\n            <tbody>\n    `;\n\n    // Loop through KPI data to populate rows\n    kpi.forEach((kpis, index) => {\n        const kpiName = kpis.kpi || \"Unknown KPI\";\n        const description = kpis.description || \"No Description\";\n        const count = kpis.field ? kpis.field_value : 0;\n        const recommendation = kpis.recommendation || \"No Action Needed\";\n\n        // Determine impact and color\n        let impact = \"Low\";\n        let impactColor = \"#52c41a\"; // Default green color for Low impact\n        if (count >= totalCount / 2) {\n            impact = \"High\";\n            impactColor = \"#ff4d4f\"; // Red for High impact\n        } else if (count > 2) {\n            impact = \"Medium\";\n            impactColor = \"#faad14\"; // Orange for Medium impact\n        }\n\n        // Row background and hover effect\n        const rowColor = index % 2 === 0 ? \"#fafafa\" : \"#ffffff\";\n        const hoverColor = \"#f0f5ff\";\n\n        // Generate table rows\n        tableHtml += `\n            <tr style=\"background-color: ${rowColor}; transition: all 0.3s;\" \n                onmouseover=\"this.style.backgroundColor='${hoverColor}'\" \n                onmouseout=\"this.style.backgroundColor='${rowColor}'\">\n                <td style=\"padding: 16px; border-bottom: 1px solid #e6f7ff;  color: #595959;\">${kpiName}</td>\n                <td style=\"padding: 16px; border-bottom: 1px solid #e6f7ff; color: #595959;\">${description}</td>\n                <td style=\"padding: 16px; text-align: center; border-bottom: 1px solid #e6f7ff;  color: #262626;\">${count}</td>\n                <td style=\"padding: 16px; text-align: center; border-bottom: 1px solid #e6f7ff;\">\n                    <span style=\"display: inline-flex; align-items: center; gap: 6px; font-weight: 600;\">\n                        <span style=\"display: inline-block; width: 12px; height: 12px; background-color: ${impactColor}; border-radius: 50%;\"></span>\n                        ${impact}\n                    </span>\n                </td>\n                <td style=\"padding: 16px; border-bottom: 1px solid #e6f7ff; color: #096dd9; font-weight: 500;\">${recommendation}</td>\n            </tr>\n        `;\n    });\n\n    // Close the table\n    tableHtml += `\n            </tbody>\n        </table>\n    `;\n\n    // Return the generated table\n    return tableHtml;\n}\n",
