                                                "html": {
                                                    "script": {
                                                        "apiVersion": "2.0.0",
                                                        "controllerElementId": null,
                                                        "inlineScript": "function evaluateProperty({ api, helpers }) {\n    const kpi = api.data.sam_kpi_foundation_1.output.department_kpi;\n    const totalCount = kpi.reduce((sum, kpis) => sum + (kpis.field ? kpis.field_value : 0), 0); // Calculate total count\n\n    // Initialize the HTML table string\n    let tableHtml = `\n <table id=\"kpi-table\" style=\"width: 100%; border-collapse: collapse; font-family: 'Arial', sans-serif; margin-top: 20px; background-color: #ffffff; border: 1px solid #dcdcdc; border-radius: 4px;\">\n            <thead>\n                <tr style=\"background-color: #f3f4f6; color: #333333; font-size: 14px; text-align: left; border-bottom: 2px solid #dcdcdc;\">\n                    <th style=\"padding: 12px; border-right: 1px solid #e0e0e0;\">KPI</th>\n                    <th style=\"padding: 12px; border-right: 1px solid #e0e0e0;\">Description</th>\n                    <th style=\"padding: 12px; text-align: center; border-right: 1px solid #e0e0e0;\">Count</th>\n                    <th style=\"padding: 12px; text-align: center; border-right: 1px solid #e0e0e0;\">Impact</th>\n                    <th style=\"padding: 12px;\">Recommendation</th>\n                </tr>\n            </thead>\n            <tbody>\n    `;\n\n    // Loop through the kpi array and generate table rows\n    kpi.forEach((kpis, index) => {\n        let kpiName = kpis.kpi || \"Unknown KPI\";\n        let description = kpis.description || \"No Description\";\n        let count = kpis.field ? kpis.field_value : 0;\n        let recommendation = kpis.recommendation || \"No Action Needed\";\n\n        // Determine impact and circle color\n        let impact = \"Low\";\n        let impactColor = \"#52c41a\"; // Green for Low\n        if (count >= totalCount / 2) {\n            impact = \"High\";\n            impactColor = \"#ff4d4f\"; // Red for High\n        } else if (count > 2) {\n            impact = \"Medium\";\n            impactColor = \"#faad14\"; // Orange for Medium\n        }\n\n        // Alternating row background color\n        const rowColor = index % 2 === 0 ? \"#f9f9f9\" : \"#ffffff\";\n        const hoverColor = \"#f0f5ff\";\n\n        tableHtml += `\n            <tr style=\"background-color: ${rowColor}; transition: all 0.3s ease;\"\n                onmouseover=\"this.style.backgroundColor='${hoverColor}'\" \n                onmouseout=\"this.style.backgroundColor='${rowColor}'\">\n                <td style=\"padding: 12px; border-bottom: 1px solid #e6e6e6;  color: #333;\">${kpiName}</td>\n                <td style=\"padding: 12px; border-bottom: 1px solid #e6e6e6; color: #555;\">${description}</td>\n                <td style=\"padding: 12px; text-align: center; border-bottom: 1px solid #e6e6e6; \">${count}</td>\n                <td style=\"padding: 12px; text-align: center; border-bottom: 1px solid #e6e6e6;\">\n                    <span style=\"\n                        display: inline-flex; \n                        align-items: center; \n                        gap: 6px; \n                        font-weight: 600; \n                        color: ${impactColor};\">\n                        <span style=\"\n                            display: inline-block; \n                            width: 12px; \n                            height: 12px; \n                            background-color: ${impactColor}; \n                            border-radius: 50%;\"></span>\n                        ${impact}\n                    </span>\n                </td>\n                <td style=\"padding: 12px; border-bottom: 1px solid #e6e6e6; font-weight: 500; color: #096dd9;\">${recommendation}</td>\n            </tr>\n        `;\n    });\n\n    // Close the table\n    tableHtml += `\n            </tbody>\n        </table>\n    `;\n\n    return tableHtml;\n}\n",
                                                        "scriptSysId": "3d96ecfac3de92500ced12f1b40131eb",
                                                        "target": null
