                        "tabStyles": {
                            "type": "JSON_LITERAL",
                            "value": "/* Container for the Tabset */\n.tabset-container {\n    display: flex;\n    flex-direction: column;\n    gap: 16px;\n    padding: 24px;\n    border-radius: 16px;\n    box-shadow: 0 4px 10px #ffffff; /* Soft, subtle shadow */\n    transition: all 0.3s ease; /* Smooth hover effect */\n}\n\n/* Individual Tabs */\n.tabset-tabs {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    max-width: 280px;\n    background-color: #ffffff; /* Core white background for light theme */\n    padding: 16px 20px;\n    border-radius: 12px;\n    border-top-left-radius: 0px;\n    transition: all 0.3s ease, transform 0.2s ease;\n    cursor: pointer;\n    position: relative;\n    overflow: hidden;\n    border: 1px solid #e0e0e0; /* Subtle border for separation */\n}\n\n/* Hover Effect for Tabs */\n.tabset-tabs:hover {\n    background-color: #ffffff; /* Light blue tint on hover for light theme */\n    box-shadow: 0 6px 15px rgba(0, 128, 255, 0.1); /* Elevated shadow for hover */\n    transform: translateY(-2px);\n}\n\n/* Active Tab */\n.tabset-tabs.active {\n    background-color: #e6f7ff; /* Light highlighted blue for active state */\n    box-shadow: 0 4px 12px rgba(0, 128, 255, 0.2);\n    font-weight: bold;\n    border-radius: 120px;\n    border-left: 12px solid #1890ff;\n}\n\n/* Tab Text Styling */\n.tabset-tabs span {\n    font-size: 16px;\n    color: #333333; /* Dark gray for better contrast */\n    font-weight: 500;\n    transition: color 0.3s ease;\n}\n\n.tabset-tabs:hover span {\n    color: #096dd9; /* Bright blue on hover for text */\n}\n\n/* Icon or Action Button */\n.tabset-tabs .tab-icon {\n    font-size: 20px;\n    color: #8c8c8c; /* Neutral gray for icons */\n    transition: color 0.3s ease, transform 0.3s ease;\n}\n\n.tabset-tabs:hover .tab-icon {\n    color: #1890ff; /* Bright blue for hover */\n}\n\n/* Responsive Styling */\n@media (max-width: 768px) {\n    .tabset-tabs {\n        width: 100%;\n        padding: 14px 16px;\n    }\n\n    .tabset-container {\n        gap: 12px;\n        padding: 16px;\n    }\n}\n"
