                                                    "script": {
                                                        "apiVersion": "2.0.0",
                                                        "controllerElementId": null,
                                                        "inlineScript": "function evaluateProperty({ api, helpers }) { \n    const kpi = api.data.sam_kpi_usage_1.output.usage_discovery_models;\n    const totalCount = kpi.reduce((sum, kpis) => sum + (kpis.field ? kpis.field_value : 0), 0);\n\n    // Start table\n    let tableHtml = `\n        <table style=\"width: 100%; border-collapse: collapse; margin-top: 20px; font-family: 'Arial', sans-serif; background-color: #f9f9f9;\">\n            <thead>\n                <tr style=\"background-color: #F1F5F9; color: black; text-align: left; font-size: 16px;\">\n                    <th style=\"padding: 12px; border: 1px solid #ddd;\">KPI</th>\n                    <th style=\"padding: 12px; border: 1px solid #ddd;\">Description</th>\n                    <th style=\"padding: 12px; border: 1px solid #ddd;\">Count</th>\n                    <th style=\"padding: 12px; border: 1px solid #ddd;\">Impact</th>\n                    <th style=\"padding: 12px; border: 1px solid #ddd;\">Recommendation</th>\n                </tr>\n            </thead>\n            <tbody>\n    `;\n\n    // Generate table rows\n    kpi.forEach(kpis => {\n        let kpiName = kpis.kpi || \"Unknown KPI\";\n        let description = kpis.description || \"No Description\";\n        let count = kpis.field ? kpis.field_value : 0;\n        let recommendation = kpis.recommendation || \"No Action Needed\";\n\n        // Determine impact and associated colors\n        let impact = \"Low\";\n        let dotColor = \"green\";\n        let rowColor = \"#ffffff\"; // Default row color\n        let rowHoverColor = \"#e6f7ff\";\n\n        if (count >= totalCount / 2) {\n            impact = \"High\";\n            dotColor = \"red\";\n        } else if (count > 2) {\n            impact = \"Medium\";\n            dotColor = \"orange\";\n        }\n\n        tableHtml += `\n            <tr style=\"background-color: ${rowColor}; transition: all 0.3s;\" \n                onmouseover=\"this.style.backgroundColor='${rowHoverColor}'\" \n                onmouseout=\"this.style.backgroundColor='${rowColor}'\">\n                <td style=\"padding: 16px; border-bottom: 1px solid #e6f7ff; font-weight: 600; color: #595959;\">${kpiName}</td>\n                <td style=\"padding: 16px; border-bottom: 1px solid #e6f7ff; color: #595959;\">${description}</td>\n                <td style=\"padding: 16px; text-align: center; border-bottom: 1px solid #e6f7ff;  color: #262626;\">${count}</td>\n                <td style=\"padding: 16px; text-align: center; border-bottom: 1px solid #e6f7ff;\">\n                    <span style=\"display: inline-flex; align-items: center; gap: 6px; font-weight: 600;\">\n                        <span style=\"display: inline-block; width: 12px; height: 12px; background-color: ${dotColor}; border-radius: 50%;\"></span>\n                        ${impact}\n                    </span>\n                </td>\n                <td style=\"padding: 16px; border-bottom: 1px solid #e6f7ff; color: #096dd9; font-weight: 500;\">${recommendation}</td>\n            </tr>\n        `;\n    });\n\n    // Close table\n    tableHtml += `\n            </tbody>\n        </table>\n    `;\n\n    // Return the final table HTML\n    return tableHtml;\n}\n",
