                                                        "inlineScript": "function evaluateProperty({ api, helpers }) {\n    const kpi = api.data.sam_kpi_usage_1.output.usage_software_models;\n    const totalCount = kpi.reduce((sum, kpis) => sum + (kpis.field ? kpis.field_value : 0), 0); // Calculate total count\n\n    // Initialize the HTML table string\n    let tableHtml = `\n        <table style=\"width: 100%; border-collapse: collapse; margin-top: 20px; font-family: 'Arial', sans-serif; background-color: #f9f9f9;border-radius: 8px; \">\n            <thead>\n                <tr style=\"background-color:#F1F5F9; color: black; text-align: left; font-size: 16px;\">\n                    <th style=\"padding: 12px; \">KPI</th>\n                    <th style=\"padding: 12px; \">Description</th>\n                    <th style=\"padding: 12px; \">Count</th>\n                    <th style=\"padding: 12px; \">Impact</th>\n                    <th style=\"padding: 12px; \">Recommendation</th>\n                </tr>\n            </thead>\n            <tbody>\n    `;\n\n    // Loop through the kpi array and generate table rows\n    kpi.forEach(kpis => {\n        let kpiName = kpis.kpi || \"Unknown KPI\"; // Assuming the KPI is the kpis ID\n        let description = kpis.description || \"No Description\";\n        let count = kpis.field ? kpis.field_value : 0; // Count is 1 if active, 0 if inactive\n        let recommendation = kpis.recommendation ? kpis.recommendation : 'No Action Needed'; // Recommendation based on active state\n\n        // Determine impact based on count and totalCount\n        let impact = \"Low\";\n        let impactColor = \"green\"; \n        let dotColor = \"green\"; // Default dot color\n        let rowColor = \"#ffffff\"; \n        let rowHoverColor = \"#e6f7ff\";\n\n        if (count >= totalCount / 2) {\n            impact = \"High\";\n            impactColor = \"red\";\n            dotColor = \"red\";\n        } else if (count > 2) {\n            impact = \"Medium\";\n            impactColor = \"orange\";\n            dotColor = \"orange\";\n        }\n\n        tableHtml += `\n            <tr style=\"background-color: ${rowColor}; transition: all 0.3s;\" \n                onmouseover=\"this.style.backgroundColor='${rowHoverColor}'\" \n                onmouseout=\"this.style.backgroundColor='${rowColor}'\">\n                <td style=\"padding: 10px; border-bottom: 1px solid #e6f7ff;  color: #595959;\">${kpiName}</td>\n                <td style=\"padding: 10px; border-bottom: 1px solid #e6f7ff; color: #595959;\">${description}</td>\n                <td style=\"padding: 10px; text-align: center; border-bottom: 1px solid #e6f7ff; fcolor: #262626;\">${count}</td>\n                <td style=\"padding: 10px; text-align: center; border-bottom: 1px solid #e6f7ff;\">\n                    <span style=\"display: inline-flex; align-items: center; gap: 6px; font-weight: 600;\">\n                        <span style=\"display: inline-block; width: 12px; height: 12px; background-color: ${dotColor}; border-radius: 50%;\"></span>\n                        ${impact}\n                    </span>\n                </td>\n                <td style=\"padding: 10px; border-bottom: 1px solid #e6f7ff; color: #096dd9; font-weight: 500;\">${recommendation}</td>\n            </tr>\n        `;\n    });\n\n    // Close the table body and table tag\n    tableHtml += '</tbody></table>';\n\n    // Return the generated HTML table\n    return tableHtml;\n}\n",
